**`openPatModal(provider)`:**
- Sets `modal.dataset.provider = provider`
- If `provider === 'github'`: title = `'Connect GitHub — Personal Access Token'`, placeholder = `'ghp_xxxx...'`, link href = `'https://github.com/settings/tokens/new?scopes=repo,read:user&description=CodeFly'`
- If `provider === 'gitlab'`: title = `'Connect GitLab — Personal Access Token'`, placeholder = `'glpat-xxxx...'`, link href = `'https://gitlab.com/-/user_settings/personal_access_tokens?name=CodeFly&scopes=read_api,read_repository'`
- Clears `#patModalInput` and `#patModalError`
- Sets `modal.style.display = 'block'`

**`window.closePatModal()`:** sets `modal.style.display = 'none'`

**`window.savePatToken()`:**
1. Read `provider` from `modal.dataset.provider`
2. Read `token` from `#patModalInput` value (trimmed)
3. If empty → set `#patModalError` text = `'Please enter a token'`, return
4. Set `#patModalError` text = `'Verifying…'`
5. If `provider === 'github'`: call `fetchGitHubViewerLogin(token)` → get `userLabel`
6. If `provider === 'gitlab'`: GET `https://gitlab.com/api/v4/user` with `Authorization: Bearer [token]` → get `data.username` as `userLabel`
7. Set `authState = { provider, token, userLabel }`, call `saveAuthState()`, call `window.closePatModal()`
8. On error: set `#patModalError` text = `err.message`

// ============================================================
// CODE AGENT - AI Agent that can interact with code
// ============================================================

const { LLMProvider } = require('./llm-provider');

class CodeAgent {
    constructor(config) {
        if (!config.id) {
            throw new Error('CodeAgent: id is required');
        }
        if (!config.name) {
            throw new Error('CodeAgent: name is required');
        }

        this.id = config.id;
        this.name = config.name;
        this.role = config.role || 'assistant';
        this.systemPrompt = config.systemPrompt || this.getDefaultSystemPrompt();

        const llmConfig = config.llm || {};
        const baseUrl = llmConfig.baseUrl || 'http://10.0.0.6:11434';
        const model = llmConfig.model || 'llama3.2';

        this.llm = new LLMProvider(baseUrl, model);
        this.conversationHistory = [];
        this.context = {
            currentFile: null,
            currentFunction: null,
            repoContext: null
        };
    }

    getDefaultSystemPrompt() {
        return `You are a code exploration agent in CodeFly, a 3D codebase visualization tool.
Your role is to help users understand code by:
- Explaining functions and their relationships
- Suggesting navigation paths through the codebase
- Identifying patterns and potential issues
- Answering questions about code structure

Be concise and direct. Focus on actionable insights.`;
    }

    async processMessage(userMessage, codeContext = null) {
        if (!userMessage || typeof userMessage !== 'string') {
            throw new Error('CodeAgent: userMessage must be a non-empty string');
        }

        const messages = this.buildMessages(userMessage, codeContext);

        try {
            const response = await this.llm.chat(messages);
            this.addToHistory('user', userMessage);
            this.addToHistory('assistant', response);
            return response;
        } catch (error) {
            throw new Error(`CodeAgent ${this.id}: ${error.message}`);
        }
    }

    buildMessages(userMessage, codeContext) {
        const messages = [
            { role: 'system', content: this.systemPrompt }
        ];

        if (codeContext) {
            const contextStr = this.formatCodeContext(codeContext);
            messages.push({
                role: 'system',
                content: `Current code context:\n${contextStr}`
            });
        }

        messages.push({ role: 'user', content: userMessage });
        return messages;
    }

    formatCodeContext(context) {
        const parts = [];

        if (context.filePath) {
            parts.push(`File: ${context.filePath}`);
        }

        if (context.functionName) {
            parts.push(`Function: ${context.functionName}`);
        }

        if (context.code) {
            parts.push(`Code:\n${context.code}`);
        }

        if (context.dependencies) {
            parts.push(`Dependencies: ${context.dependencies.join(', ')}`);
        }

        return parts.join('\n');
    }

    addToHistory(role, content) {
        this.conversationHistory.push({ role, content });

        if (this.conversationHistory.length > 20) {
            this.conversationHistory = this.conversationHistory.slice(-20);
        }
    }

    setContext(context) {
        if (!context || typeof context !== 'object') {
            throw new Error('CodeAgent: context must be an object');
        }
        this.context = { ...this.context, ...context };
    }

    clearHistory() {
        this.conversationHistory = [];
    }

    getPosition() {
        return this.position || { x: 0, y: 0, z: 0 };
    }

    setPosition(x, y, z) {
        this.position = { x, y, z };
    }

    toJSON() {
        return {
            id: this.id,
            name: this.name,
            role: this.role,
            position: this.getPosition(),
            context: this.context
        };
    }
}

module.exports = { CodeAgent };

const Database = require('better-sqlite3');
const path = require('path');
const { v4: uuidv4 } = require('uuid');

const DB_PATH = process.env.DB_PATH || path.join(__dirname, 'codechat.db');
const db = new Database(DB_PATH);

db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY,
    github_id INTEGER UNIQUE NOT NULL,
    github_login TEXT NOT NULL,
    github_name TEXT,
    github_avatar TEXT,
    email TEXT,
    plan TEXT NOT NULL DEFAULT 'free',
    upgraded_at TEXT,
    repos_generated INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  );

  CREATE TABLE IF NOT EXISTS sessions (
    token TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id),
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    expires_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS graphs (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id),
    repo_url TEXT NOT NULL,
    node_count INTEGER NOT NULL DEFAULT 0,
    edge_count INTEGER NOT NULL DEFAULT 0,
    languages TEXT,
    graph_data TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  );

  CREATE INDEX IF NOT EXISTS idx_sessions_token ON sessions(token);
  CREATE INDEX IF NOT EXISTS idx_graphs_user ON graphs(user_id);
  CREATE INDEX IF NOT EXISTS idx_graphs_url ON graphs(repo_url);
`);

const FREE_REPO_LIMIT = 2;

function findUserByGithubId(githubId) {
  return db.prepare('SELECT * FROM users WHERE github_id = ?').get(githubId);
}

function createUser(githubId, login, name, avatar, email) {
  const id = uuidv4();
  db.prepare(`
    INSERT INTO users (id, github_id, github_login, github_name, github_avatar, email)
    VALUES (?, ?, ?, ?, ?, ?)
  `).run(id, githubId, login, name, avatar, email);
  return db.prepare('SELECT * FROM users WHERE id = ?').get(id);
}

function updateUser(id, login, name, avatar, email) {
  db.prepare(`
    UPDATE users SET github_login = ?, github_name = ?, github_avatar = ?, email = ?, updated_at = datetime('now')
    WHERE id = ?
  `).run(login, name, avatar, email, id);
  return db.prepare('SELECT * FROM users WHERE id = ?').get(id);
}

function createSession(userId) {
  const token = uuidv4();
  const expires = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();
  db.prepare('INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)').run(token, userId, expires);
  return token;
}

function getUserBySession(token) {
  if (!token) return null;
  const row = db.prepare(`
    SELECT u.* FROM users u
    JOIN sessions s ON s.user_id = u.id
    WHERE s.token = ? AND s.expires_at > datetime('now')
  `).get(token);
  return row;
}

function deleteSession(token) {
  db.prepare('DELETE FROM sessions WHERE token = ?').run(token);
}

function incrementRepoCount(userId) {
  db.prepare("UPDATE users SET repos_generated = repos_generated + 1, updated_at = datetime('now') WHERE id = ?").run(userId);
}

function canGenerateRepo(user) {
  if (user.plan === 'pro') return true;
  return user.repos_generated < FREE_REPO_LIMIT;
}

function saveGraph(userId, repoUrl, graphData) {
  const id = uuidv4();
  const nodeCount = graphData.nodes.length;
  const edgeCount = graphData.edges.length;
  const languages = JSON.stringify(graphData.meta.languages);
  db.prepare(`
    INSERT INTO graphs (id, user_id, repo_url, node_count, edge_count, languages, graph_data)
    VALUES (?, ?, ?, ?, ?, ?, ?)
  `).run(id, userId, repoUrl, nodeCount, edgeCount, languages, JSON.stringify(graphData));
  return id;
}

function getGraphByUrl(repoUrl) {
  const row = db.prepare('SELECT * FROM graphs WHERE repo_url = ? ORDER BY created_at DESC LIMIT 1').get(repoUrl);
  if (!row) return null;
  return JSON.parse(row.graph_data);
}

function getUserGraphs(userId) {
  return db.prepare(`
    SELECT id, repo_url, node_count, edge_count, languages, created_at
    FROM graphs WHERE user_id = ? ORDER BY created_at DESC LIMIT 20
  `).all(userId);
}

function setUserPlan(userId, plan) {
  const upgradedAt = plan === 'pro' ? new Date().toISOString() : null;
  db.prepare(`
    UPDATE users SET plan = ?, upgraded_at = ?, updated_at = datetime('now')
    WHERE id = ?
  `).run(plan, upgradedAt, userId);
}

module.exports = {
  db,
  FREE_REPO_LIMIT,
  findUserByGithubId,
  createUser,
  updateUser,
  createSession,
  getUserBySession,
  deleteSession,
  incrementRepoCount,
  canGenerateRepo,
  saveGraph,
  getGraphByUrl,
  getUserGraphs,
  setUserPlan,
};

