    ],
    rust: [
      /^\s*use\s+([a-zA-Z0-9_:]+)/gm,
      /^\s*(?:extern\s+crate|mod)\s+([a-zA-Z0-9_]+)/gm,
    ],
    csharp: [
      /^\s*using\s+(?:static\s+)?([a-zA-Z0-9_.]+)/gm,
    ],
    ruby: [
      /^\s*require\s+['"]([^'"]+)['"]/gm,
      /^\s*require_relative\s+['"]([^'"]+)['"]/gm,
    ],
    php: [
      /^\s*(?:use|include|include_once|require|require_once)\s+['"]?([^'";]+)/gm,
    ],
    swift: [
      /^\s*import\s+(\S+)/gm,
    ],
    kotlin: [
      /^\s*import\s+([a-zA-Z0-9_.]+)/gm,
    ],
    scala: [
      /^\s*import\s+([a-zA-Z0-9_.{}]+)/gm,
    ],
    c: [
      /^\s*#include\s+["<]([^">]+)[">]/gm,
    ],
    cpp: [
      /^\s*#include\s+["<]([^">]+)[">]/gm,
    ],
    html: [
      /<script\s+[^>]*src=["']([^"']+)["']/gi,
      /<link\s+[^>]*href=["']([^"']+)["']/gi,
      /import\s+.*?from\s+['"]([^'"]+)['"]/g,
      /require\s*\(\s*['"]([^'"]+)['"]\s*\)/g,
    ],
    css: [
      /@import\s+(?:url\s*\(\s*)?['"]?([^'");\s]+)['"]?\s*\)?\s*;/gm,
    ],
    vue: [
      /import\s+.*?from\s+['"]([^'"]+)['"]/g,
      /require\s*\(\s*['"]([^'"]+)['"]\s*\)/g,
      /<script\s+[^>]*src=["']([^"']+)["']/gi,
    ],
    svelte: [
      /import\s+.*?from\s+['"]([^'"]+)['"]/g,
    ],
    shell: [
      /^\s*(?:source|\.)\s+['"]?([^'";\s]+)['"]?/gm,
    ],
    sql: [],
    json: [],
    yaml: [],
    markdown: [],
    xml: [],
    toml: [],
    env: [],
    docker: [],
  };

  const langPatterns = patterns[lang];
  if (!langPatterns) return imports;

  for (const pattern of langPatterns) {
    let match;
    while ((match = pattern.exec(content)) !== null) {
      imports.add(match[1]);
    }
  }
  return imports;
}

// ============================================================
// DEFINITION EXTRACTION (per language) — functions, classes, variables
// ============================================================
const SKIP_KEYWORDS = new Set([
  'if', 'else', 'for', 'while', 'switch', 'catch', 'return',
  'new', 'throw', 'typeof', 'delete', 'void', 'try', 'finally',
  'do', 'break', 'continue', 'case', 'default', 'with',
]);

function extractDefinitionsFromContent(content, lang) {
  const defs = [];
  const seen = new Set();

  // Each entry: [regex, kind]
  const patterns = {
    javascript: [
      // functions
      [/^\s*(?:async\s+)?function\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(/gm, 'function'],
      [/^\s*export\s+(?:async\s+)?function\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(/gm, 'function'],
      [/^\s*(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=\s*(?:async\s+)?(?:\([^)]*\)|[a-zA-Z_$][a-zA-Z0-9_$]*)\s*=>/gm, 'function'],
      [/^\s*(?:async\s+)?([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\([^)]*\)\s*\{/gm, 'function'],
      [/(?:module\.)?exports\.([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=/gm, 'function'],
      // classes
      [/^\s*class\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/gm, 'class'],
      // variables (top-level only — no indentation)
      [/^(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=\s*(?!(?:async\s+)?(?:\([^)]*\)|[a-zA-Z_$][a-zA-Z0-9_$]*)\s*=>)/gm, 'variable'],
    ],
    typescript: [
      // functions
      [/^\s*(?:export\s+)?(?:async\s+)?function\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/gm, 'function'],
      [/^\s*(?:export\s+)?(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=\s*(?:async\s+)?(?:\([^)]*\)|[a-zA-Z_$][a-zA-Z0-9_$]*)\s*=>/gm, 'function'],
      [/^\s*(?:public|private|protected|static|async)*\s*([a-zA-Z_$][a-zA-Z0-9_$]*)\s*[<(]/gm, 'function'],
      // classes
      [/^\s*(?:export\s+)?(?:abstract\s+)?class\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/gm, 'class'],
      [/^\s*(?:export\s+)?interface\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/gm, 'class'],
      [/^\s*(?:export\s+)?enum\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/gm, 'class'],
      // variables (top-level or exported only)
      [/^(?:export\s+)?type\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/gm, 'variable'],
      [/^(?:export\s+)?(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*(?::[^=]+)?\s*=\s*(?!(?:async\s+)?(?:\([^)]*\)|[a-zA-Z_$][a-zA-Z0-9_$]*)\s*=>)/gm, 'variable'],
    ],
    python: [
      // functions
      [/^\s*def\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/gm, 'function'],
      [/^\s*async\s+def\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/gm, 'function'],
      // classes
      [/^\s*class\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      // variables (module-level assignments, UPPER_CASE constants)
      [/^([A-Z][A-Z0-9_]*)\s*=/gm, 'variable'],
    ],
    go: [
      // functions
      [/^\s*func\s+(?:\([^)]*\)\s+)?([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/gm, 'function'],
      // classes (structs/interfaces)
      [/^\s*type\s+([a-zA-Z_][a-zA-Z0-9_]*)\s+(?:struct|interface)/gm, 'class'],
      // variables
      [/^\s*(?:var|const)\s+([a-zA-Z_][a-zA-Z0-9_]*)\s/gm, 'variable'],
    ],
    java: [
      // functions
      [/^\s*(?:public|private|protected|static|final|abstract|synchronized|native)*\s*(?:[a-zA-Z_<>\[\]]+\s+)+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/gm, 'function'],
      // classes
      [/^\s*(?:public|private|protected)?\s*(?:abstract\s+)?class\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:public\s+)?interface\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:public\s+)?enum\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      // variables (static final = constants)
      [/^\s*(?:public|private|protected)?\s*static\s+final\s+\S+\s+([A-Z][A-Z0-9_]*)\s*=/gm, 'variable'],
    ],
    rust: [
      // functions
      [/^\s*(?:pub\s+)?(?:async\s+)?fn\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'function'],
      // classes
      [/^\s*(?:pub\s+)?struct\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:pub\s+)?enum\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:pub\s+)?trait\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*impl(?:<[^>]*>)?\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      // variables
      [/^\s*(?:pub\s+)?(?:static|const)\s+(?:mut\s+)?([A-Z][A-Z0-9_]*)\s*:/gm, 'variable'],
      [/^\s*let\s+(?:mut\s+)?([a-zA-Z_][a-zA-Z0-9_]*)\s*/gm, 'variable'],
    ],
    csharp: [
      // functions
      [/^\s*(?:public|private|protected|internal|static|virtual|override|abstract|async)*\s*(?:[a-zA-Z_<>\[\]]+\s+)+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/gm, 'function'],
      // classes
      [/^\s*(?:public|private|protected|internal)?\s*(?:abstract|static|sealed|partial)*\s*class\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:public\s+)?interface\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:public\s+)?enum\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      // variables
      [/^\s*(?:public|private|protected|internal)?\s*(?:static\s+)?(?:readonly\s+)?\S+\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*[=;]/gm, 'variable'],
    ],
    ruby: [
      // functions
      [/^\s*def\s+(?:self\.)?([a-zA-Z_][a-zA-Z0-9_!?]*)/gm, 'function'],
      // classes
      [/^\s*class\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*module\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      // variables (constants)
      [/^\s*([A-Z][A-Z0-9_]*)\s*=/gm, 'variable'],
    ],
    php: [
      // functions
      [/^\s*(?:public|private|protected|static)*\s*function\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/gm, 'function'],
      // classes
      [/^\s*class\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*interface\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*trait\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      // variables (class constants, define)
      [/^\s*const\s+([A-Z][A-Z0-9_]*)\s*=/gm, 'variable'],
      [/^\s*define\s*\(\s*['"]([A-Z][A-Z0-9_]*)['"]/gm, 'variable'],
    ],
    swift: [
      // functions
      [/^\s*(?:public|private|internal|open|fileprivate)?\s*(?:static|class)?\s*func\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'function'],
      // classes
      [/^\s*(?:public|private|internal|open)?\s*class\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:public|private|internal|open)?\s*struct\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:public|private|internal|open)?\s*protocol\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:public|private|internal|open)?\s*enum\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      // variables
      [/^\s*(?:public|private|internal|open)?\s*(?:static\s+)?(?:let|var)\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*[=:]/gm, 'variable'],
    ],
    kotlin: [
      // functions
      [/^\s*(?:public|private|protected|internal|open|override|abstract)?\s*(?:suspend\s+)?fun\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'function'],
      // classes
      [/^\s*(?:public|private|protected|internal|open|abstract|data|sealed)?\s*class\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:public\s+)?interface\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:public\s+)?enum\s+class\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:public\s+)?object\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      // variables
      [/^\s*(?:public|private|protected|internal)?\s*(?:val|var)\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*[=:]/gm, 'variable'],
    ],
    scala: [
      // functions
      [/^\s*def\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'function'],
      // classes
      [/^\s*(?:case\s+)?class\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*trait\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*object\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      // variables
      [/^\s*(?:val|var)\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*[=:]/gm, 'variable'],
    ],
    c: [
      // functions
      [/^\s*(?:static\s+)?(?:inline\s+)?(?:const\s+)?(?:unsigned\s+)?(?:signed\s+)?(?:long\s+)?(?:short\s+)?(?:void|int|char|float|double|bool|size_t|[a-zA-Z_]\w*\s*\*?)\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/gm, 'function'],
      // classes
      [/^\s*(?:typedef\s+)?struct\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*(?:typedef\s+)?enum\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      // variables
      [/^\s*#define\s+([A-Z][A-Z0-9_]*)/gm, 'variable'],
    ],
    cpp: [
      // functions
      [/^\s*(?:static\s+)?(?:inline\s+)?(?:virtual\s+)?(?:const\s+)?(?:void|int|char|float|double|bool|auto|std::\w+|[a-zA-Z_]\w*(?:<[^>]*>)?)\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/gm, 'function'],
      // classes
      [/^\s*class\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*struct\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      [/^\s*namespace\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm, 'class'],
      // variables
      [/^\s*#define\s+([A-Z][A-Z0-9_]*)/gm, 'variable'],
      [/^\s*(?:const|constexpr)\s+\S+\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*=/gm, 'variable'],
    ],
    html: [
      // JS functions inside <script> tags
      [/^\s*(?:async\s+)?function\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(/gm, 'function'],
      [/^\s*(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=\s*(?:async\s+)?(?:\([^)]*\)|[a-zA-Z_$][a-zA-Z0-9_$]*)\s*=>/gm, 'function'],
      [/^\s*(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=\s*function/gm, 'function'],
      // HTML element IDs
      [/\bid=["']([a-zA-Z_][a-zA-Z0-9_-]*)["']/gi, 'variable'],
      // CSS classes in HTML
      [/\bclass=["']([a-zA-Z_][a-zA-Z0-9_ -]*)["']/gi, 'class'],
    ],
    css: [
      // CSS custom properties
      [/^\s*(--[a-zA-Z][a-zA-Z0-9-]*)\s*:/gm, 'variable'],
      // @keyframes
      [/@keyframes\s+([a-zA-Z_][a-zA-Z0-9_-]*)/gm, 'function'],
      // class selectors (top-level)
      [/^\.([a-zA-Z_][a-zA-Z0-9_-]*)\s*[{,]/gm, 'class'],
      // ID selectors
      [/^#([a-zA-Z_][a-zA-Z0-9_-]*)\s*[{,]/gm, 'variable'],
    ],
    vue: [
      // same as JS
      [/^\s*(?:async\s+)?function\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(/gm, 'function'],
      [/^\s*(?:export\s+)?(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=\s*(?:async\s+)?(?:\([^)]*\)|[a-zA-Z_$][a-zA-Z0-9_$]*)\s*=>/gm, 'function'],
      [/^\s*(?:async\s+)?([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\([^)]*\)\s*\{/gm, 'function'],
      [/^\s*(?:export\s+)?(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=/gm, 'variable'],
    ],
    svelte: [
      [/^\s*(?:async\s+)?function\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(/gm, 'function'],
      [/^\s*(?:export\s+)?(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=\s*(?:async\s+)?(?:\([^)]*\)|[a-zA-Z_$][a-zA-Z0-9_$]*)\s*=>/gm, 'function'],
      [/^\s*(?:export\s+)?(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=/gm, 'variable'],
    ],
    shell: [
      // functions
      [/^\s*(?:function\s+)?([a-zA-Z_][a-zA-Z0-9_]*)\s*\(\s*\)\s*\{/gm, 'function'],
      // exported variables
      [/^\s*export\s+([A-Z][A-Z0-9_]*)=/gm, 'variable'],
      // top-level variable assignments (UPPER_CASE)
      [/^([A-Z][A-Z0-9_]*)=/gm, 'variable'],
    ],
    sql: [
      [/^\s*CREATE\s+(?:OR\s+REPLACE\s+)?TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?(?:`|")?([a-zA-Z_][a-zA-Z0-9_]*)(?:`|")?/gim, 'class'],
      [/^\s*CREATE\s+(?:OR\s+REPLACE\s+)?VIEW\s+(?:`|")?([a-zA-Z_][a-zA-Z0-9_]*)(?:`|")?/gim, 'class'],
      [/^\s*CREATE\s+(?:OR\s+REPLACE\s+)?(?:FUNCTION|PROCEDURE)\s+(?:`|")?([a-zA-Z_][a-zA-Z0-9_]*)(?:`|")?/gim, 'function'],
      [/^\s*CREATE\s+(?:OR\s+REPLACE\s+)?INDEX\s+(?:`|")?([a-zA-Z_][a-zA-Z0-9_]*)(?:`|")?/gim, 'variable'],
    ],
    markdown: [
      // headings as sections
      [/^#{1,3}\s+(.+)$/gm, 'class'],
    ],
    json: [],
    yaml: [
      // top-level keys
      [/^([a-zA-Z_][a-zA-Z0-9_-]*):/gm, 'variable'],
    ],
    xml: [],
    toml: [
      // section headers
      [/^\[([a-zA-Z_][a-zA-Z0-9_.]*)\]/gm, 'class'],
    ],
    env: [
      // env variable names
      [/^([A-Z][A-Z0-9_]*)=/gm, 'variable'],
    ],
    docker: [
      // Dockerfile instructions as definitions
      [/^(FROM|RUN|CMD|ENTRYPOINT|EXPOSE|ENV|COPY|ADD|WORKDIR|VOLUME|ARG)\s/gm, 'function'],
    ],
  };

  const langPatterns = patterns[lang];
  if (!langPatterns) return defs;

  for (const [pattern, kind] of langPatterns) {
    let match;
    while ((match = pattern.exec(content)) !== null) {
      const name = match[1];
      if (!seen.has(name) && !SKIP_KEYWORDS.has(name) && name.length > 1) {
        seen.add(name);
        const lineNum = content.substring(0, match.index).split('\n').length;
        defs.push({ name, line: lineNum, kind });
      }
    }
  }
  return defs;
}

function escapeRegexLiteral(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function buildSymbolMatchers(names) {
  return names.map((name) => {
    const escaped = escapeRegexLiteral(name);
    return {
      name,
      call: new RegExp(`(^|[^\\w$])(?:new\\s+)?${escaped}\\s*\\(`),
      usage: new RegExp(`(^|[^\\w$])${escaped}([^\\w$]|$)`),
      declaration: new RegExp(`\\b(function|class|const|let|var|type|interface|enum|def|fn|func)\\s+${escaped}\\b`),
    };
  });
}

function extractSymbolReferences(content, knownDefinitions) {
  if (typeof content !== 'string' || content.length === 0 || !Array.isArray(knownDefinitions)) return [];
  const names = [...new Set(knownDefinitions.map((def) => def.name).filter(Boolean))];
  if (names.length === 0) return [];
  const refs = [];
  const seen = new Set();
  const matchers = buildSymbolMatchers(names);
  const lines = content.split('\n');

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    for (const matcher of matchers) {
      if (matcher.declaration.test(line)) continue;
      if (!matcher.call.test(line) && !matcher.usage.test(line)) continue;
      const key = `${matcher.name}@${i + 1}`;
      if (seen.has(key)) continue;
      seen.add(key);
      refs.push({ name: matcher.name, line: i + 1 });
    }
  }
  return refs;
}

function findContainingDefinition(definitions, line) {
  if (!Array.isArray(definitions) || definitions.length === 0) return null;
  const sorted = [...definitions].sort((a, b) => a.line - b.line);
  let nearest = null;
  let nearestFunction = null;

  for (const def of sorted) {
    if (def.line > line) break;
    nearest = def;
    if (def.kind === 'function') nearestFunction = def;
  }
  return nearestFunction || nearest;
}

function buildSymbolDefinitionIndex(nodes) {
  const symbolIndex = new Map();
  for (const node of nodes) {
    for (const def of node.definitions || []) {
      if (!symbolIndex.has(def.name)) symbolIndex.set(def.name, []);
      symbolIndex.get(def.name).push({ file: node.id, def });
    }
  }
  return symbolIndex;
}

function buildDefinitionsByFile(nodes) {
  const definitionsByFile = new Map();
  for (const node of nodes) {
    definitionsByFile.set(node.id, node.definitions || []);
  }
  return definitionsByFile;
}

function buildReferenceCandidates(fileId, definitionsByFile, importsByFile) {
  const byName = new Map();
  const addDefs = (defs) => {
    for (const def of defs || []) {
      if (!def || !def.name || byName.has(def.name)) continue;
      byName.set(def.name, def);
    }
  };

  addDefs(definitionsByFile.get(fileId));
  for (const importedFile of importsByFile.get(fileId) || []) {
    addDefs(definitionsByFile.get(importedFile));
  }
  return Array.from(byName.values());
}

function resolveSymbolTargets(fromFile, refName, symbolIndex, importsByFile) {
  const candidates = symbolIndex.get(refName) || [];
  if (candidates.length === 0) return [];
  const sameFile = candidates.filter((candidate) => candidate.file === fromFile);
  if (sameFile.length > 0) return sameFile;
  const importedFiles = importsByFile.get(fromFile) || new Set();
  return candidates.filter((candidate) => importedFiles.has(candidate.file));
}

function addSymbolEdge(symbolEdges, seen, fromFile, sourceDef, target, callLine) {
  if (fromFile === target.file && sourceDef.name === target.def.name) return;
  const key = `${fromFile}|${sourceDef.name}|${target.file}|${target.def.name}|${callLine}`;
  if (seen.has(key)) return;
  seen.add(key);
  symbolEdges.push({
    fromFile,
    toFile: target.file,
    fromSymbol: sourceDef.name,
    toSymbol: target.def.name,
    fromKind: sourceDef.kind || 'function',
    toKind: target.def.kind || 'function',
    fromLine: sourceDef.line || 0,
    toLine: target.def.line || 0,
    callLine,
    type: 'static-call',
  });
}

function buildSymbolEdges(nodes, importsByFile, refsByFile) {
  const symbolEdges = [];
  const seen = new Set();
  const symbolIndex = buildSymbolDefinitionIndex(nodes);
  const definitionsByFile = buildDefinitionsByFile(nodes);

  for (const node of nodes) {
    const content = refsByFile.get(node.id) || '';
    const candidates = buildReferenceCandidates(node.id, definitionsByFile, importsByFile);
    if (candidates.length === 0) continue;
    const refs = extractSymbolReferences(content, candidates);
    const definitions = node.definitions || [];
    for (const ref of refs) {
      const sourceDef = findContainingDefinition(definitions, ref.line);
      if (!sourceDef) continue;
      const targets = resolveSymbolTargets(node.id, ref.name, symbolIndex, importsByFile);
      for (const target of targets) {
        addSymbolEdge(symbolEdges, seen, node.id, sourceDef, target, ref.line);
      }
    }
  }
  return symbolEdges;
}

// ============================================================
// IMPORT RESOLUTION
// ============================================================
function resolveImport(importPath, fromFile, fileSet, lang, rootDir) {
  if (lang === 'python') {
    const pyPath = importPath.replace(/\./g, '/');
    const fromDir = path.dirname(fromFile);
    const candidates = [
      path.resolve(rootDir, pyPath + '.py'),
      path.resolve(rootDir, pyPath, '__init__.py'),
      path.resolve(fromDir, pyPath + '.py'),
      path.resolve(fromDir, pyPath, '__init__.py'),
    ];
    for (const c of candidates) {
      if (fileSet.has(c)) return c;
    }
    return null;
  }

  if (lang === 'javascript' || lang === 'typescript') {
    if (!importPath.startsWith('.') && !importPath.startsWith('/')) return null;
    const fromDir = path.dirname(fromFile);
    const resolved = path.resolve(fromDir, importPath);
    const exts = lang === 'typescript'
      ? ['', '.ts', '.tsx', '.js', '.jsx', '/index.ts', '/index.tsx', '/index.js']
      : ['', '.js', '.mjs', '.jsx', '/index.js'];
    for (const ext of exts) {
      if (fileSet.has(resolved + ext)) return resolved + ext;
    }
    return null;
  }

  if (lang === 'go') {
    return null;
  }

  if (lang === 'ruby') {
    if (!importPath.startsWith('.')) return null;
    const fromDir = path.dirname(fromFile);
    const resolved = path.resolve(fromDir, importPath);
    const candidates = [resolved, resolved + '.rb'];
    for (const c of candidates) {
      if (fileSet.has(c)) return c;
    }
    return null;
  }

  if (lang === 'c' || lang === 'cpp') {
    if (importPath.startsWith('<')) return null;
    const fromDir = path.dirname(fromFile);
    const resolved = path.resolve(fromDir, importPath);
    if (fileSet.has(resolved)) return resolved;
    return null;
  }

  if (lang === 'html' || lang === 'css' || lang === 'vue' || lang === 'svelte') {
    if (importPath.startsWith('http://') || importPath.startsWith('https://') || importPath.startsWith('//')) return null;
    const fromDir = path.dirname(fromFile);
    const resolved = path.resolve(fromDir, importPath);
    if (fileSet.has(resolved)) return resolved;
    return null;
  }

  return null;
}

function buildPreviewLines(content, maxLines = 8) {
  if (typeof content !== 'string' || content.length === 0) {
    return [];
  }
  return content
    .split('\n')
    .filter((line) => line.trim().length > 0)
    .slice(0, maxLines)
    .map((line) => (line.length > 120 ? line.substring(0, 120) + '...' : line));
}

function buildRawPreview(content, maxLines = 3) {
  if (typeof content !== 'string' || content.length === 0) {
    return [];
  }
  return content
    .split('\n')
    .slice(0, maxLines)
    .map((line) => (line.length > 180 ? line.substring(0, 180) + '...' : line));
}

function getParseProfile(file, content) {
  const lang = file.lang || 'unknown';
  const hasContent = typeof content === 'string' && content.length > 0;

  if (lang === 'unknown') {
    const extLabel = file.ext || 'unknown extension';
    return {
      parseStatus: PARSE_STATUS_UNSUPPORTED,
      parseReason: `No parser configured for ${extLabel}`,
    };
  }

  if (!hasContent) {
    return {
      parseStatus: PARSE_STATUS_PARTIAL,
      parseReason: 'Source content unavailable; showing file metadata only',
    };
  }

  if (PARTIAL_PARSE_LANGS.has(lang)) {
    return {
      parseStatus: PARSE_STATUS_PARTIAL,
      parseReason: `Lightweight parser mode for ${lang}`,
    };
  }

  return {
    parseStatus: PARSE_STATUS_FULL,
    parseReason: `Parser active for ${lang}`,
  };
}

// ============================================================
// GENERATE GRAPH (reusable function)
// ============================================================
/** @returns {GraphData} */
function generateGraph(directory) {
  const skippedExts = new Set();
  const allFiles = walkDir(directory, skippedExts);
  const fileSet = new Set(allFiles.map((file) => file.fullPath));

  const nodes = [];
  const edges = [];
  const importsByFile = new Map();
  const refsByFile = new Map();
  /** @type {Record<string, number>} */
  const langStats = {};
  const parseSummary = {
    [PARSE_STATUS_FULL]: 0,
    [PARSE_STATUS_PARTIAL]: 0,
    [PARSE_STATUS_UNSUPPORTED]: 0,
  };

  for (const file of allFiles) {
    const lang = file.lang || 'unknown';
    langStats[lang] = (langStats[lang] || 0) + 1;

    const relPath = path.relative(directory, file.fullPath);
    const folder = path.dirname(relPath).split(path.sep)[0] || '_root';

    let content = '';
    try {
      content = fs.readFileSync(file.fullPath, 'utf-8');
    } catch {
      content = '';
    }

    const allLines = content.length > 0 ? content.split('\n') : [];
    const lines = allLines.length;
    const { parseStatus, parseReason } = getParseProfile(file, content);
    parseSummary[parseStatus] = (parseSummary[parseStatus] || 0) + 1;

    const definitions = parseStatus === PARSE_STATUS_UNSUPPORTED || content.length === 0
      ? []
      : extractDefinitionsFromContent(content, lang);
    const imports = parseStatus === PARSE_STATUS_UNSUPPORTED || content.length === 0
      ? new Set()
      : extractImportsFromContent(content, lang);

    const previewLines = buildPreviewLines(content);
    const rawPreview = buildRawPreview(content);

    let fileSize = 0;
    try {
      fileSize = fs.statSync(file.fullPath).size;
    } catch {
      fileSize = 0;
    }

    nodes.push({
      id: relPath,
      label: path.basename(relPath),
      folder: folder,
      lines: lines,
      fullPath: relPath,
      definitions: definitions,
      lang: lang,
      preview: previewLines,
      rawPreview,
      content: content,
      parseStatus,
      parseReason,
      size: fileSize,
    });

    refsByFile.set(relPath, content);
    const resolvedImports = new Set();
    for (const imp of imports) {
      const resolved = resolveImport(imp, file.fullPath, fileSet, lang, directory);
      if (!resolved) continue;
      const targetRel = path.relative(directory, resolved);
      edges.push({ from: relPath, to: targetRel });
      resolvedImports.add(targetRel);
    }
    importsByFile.set(relPath, resolvedImports);
  }

  const symbolEdges = buildSymbolEdges(nodes, importsByFile, refsByFile);

  /** @type {GraphData} */
  const graphData = {
    nodes,
    edges,
    symbolEdges,
    meta: {
      languages: langStats,
      parseSummary,
      unsupportedExtensions: Array.from(skippedExts).sort(),
      totalFiles: allFiles.length,
      generatedAt: new Date().toISOString(),
    },
  };
  return graphData;
}

function cloneRepo(gitUrl) {
  const tmpDir = path.join(__dirname, '.tmp-repo-' + Date.now());
  execSync(`git clone --depth 1 ${gitUrl} ${tmpDir}`, { stdio: 'pipe' });
  return tmpDir;
}

module.exports = { generateGraph, cloneRepo };

// ============================================================
// CLI MODE
// ============================================================
if (require.main === module) {
  const TARGET_DIR = process.argv[2];
  if (!TARGET_DIR) {
    throw new Error('Usage: node generate-graph.js <directory-or-git-url>');
  }

  let scanDir;
  let needsCleanup = false;
  let repoKey;

  if (TARGET_DIR.startsWith('http://') || TARGET_DIR.startsWith('https://') || TARGET_DIR.startsWith('git@')) {
    scanDir = cloneRepo(TARGET_DIR);
    needsCleanup = true;
    repoKey = getRepoKey(TARGET_DIR, 'main');
  } else {
    scanDir = path.resolve(TARGET_DIR);
    repoKey = getRepoKey(scanDir, 'local');
  }

  const graphData = generateGraph(scanDir);

  if (needsCleanup) {
    fs.rmSync(scanDir, { recursive: true });
    console.log('Cleaned up cloned repo');
  }

  // Compute new hashes and check for incremental sync
  const newHashes = {};
  for (const node of graphData.nodes) {
    newHashes[node.id] = computeHash(node.content || '');
  }

  const cached = loadCache(repoKey);
  if (cached && cached.graphData && cached.hashMap) {
    const diff = diffHashes(cached.hashMap, newHashes);
    if (diff.changed.length === 0 && diff.added.length === 0 && diff.removed.length === 0) {
      console.log('No changes detected, using cached graph');
      graphData = cached.graphData;
    }
  }

  saveCache(repoKey, graphData, newHashes);

  const outputFile = path.join(__dirname, 'graph-data.js');
  fs.writeFileSync(outputFile, `var graphData = ${JSON.stringify(graphData, null, 2)};`);

  console.log(`Nodes: ${graphData.nodes.length}`);
  console.log(`Edges: ${graphData.edges.length}`);
  console.log(`Languages:`, graphData.meta.languages);
  console.log(`Written to ${outputFile}`);
}

// Node.js file-based cache for generate-graph.js CLI
// Uses .cache/ directory for storing graph data and hashes

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const CACHE_DIR = path.join(__dirname, '.cache');

function ensureCacheDir() {
  if (!fs.existsSync(CACHE_DIR)) {
    fs.mkdirSync(CACHE_DIR, { recursive: true });
  }
}

function getRepoKey(repoUrl, branch = 'main') {
  const safe = repoUrl.replace(/[^a-zA-Z0-9_-]/g, '_');
  return `${safe}#${branch}`;
}

function getCachePath(repoKey, type) {
  ensureCacheDir();
  return path.join(CACHE_DIR, `${repoKey}.${type}.json`);
}

function saveCachedGraph(repoKey, graphData) {
  const cachePath = getCachePath(repoKey, 'graph');
  fs.writeFileSync(cachePath, JSON.stringify(graphData, null, 2));
}

function loadCachedGraph(repoKey) {
  const cachePath = getCachePath(repoKey, 'graph');
  if (!fs.existsSync(cachePath)) return null;
  try {
    const raw = fs.readFileSync(cachePath, 'utf8');
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function saveCachedHashes(repoKey, hashMap) {
  const cachePath = getCachePath(repoKey, 'hashes');
  fs.writeFileSync(cachePath, JSON.stringify(hashMap, null, 2));
}

function loadCachedHashes(repoKey) {
  const cachePath = getCachePath(repoKey, 'hashes');
  if (!fs.existsSync(cachePath)) return null;
  try {
    const raw = fs.readFileSync(cachePath, 'utf8');
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function deleteCache(repoKey) {
  const graphPath = getCachePath(repoKey, 'graph');
  const hashPath = getCachePath(repoKey, 'hashes');
  if (fs.existsSync(graphPath)) fs.unlinkSync(graphPath);
  if (fs.existsSync(hashPath)) fs.unlinkSync(hashPath);
}

function saveCache(repoKey, graphData, hashMap) {
  saveCachedGraph(repoKey, graphData);
  saveCachedHashes(repoKey, hashMap);
}

function loadCache(repoKey) {
  const graphData = loadCachedGraph(repoKey);
  const hashMap = loadCachedHashes(repoKey);
  if (!graphData || !hashMap) return null;
  return { graphData, hashMap };
}

function computeHash(content) {
  return crypto.createHash('sha256').update(content || '').digest('hex');
}

module.exports = {
  getRepoKey,
  saveCachedGraph,
  loadCachedGraph,
  saveCachedHashes,
  loadCachedHashes,
  deleteCache,
  saveCache,
  loadCache,
  computeHash,
};

// Graph cache for incremental sync
// Uses IndexedDB for graphData (large) and localStorage for file hashes (small)

const DB_NAME = 'codefly-graph-cache';
const DB_VERSION = 1;
const STORE_NAME = 'graphs';
const HASH_PREFIX = 'codefly-hashes-';

function getRepoKey(repoUrl, branch = 'main') {
  return `${repoUrl}#${branch}`;
}

// IndexedDB operations
async function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);
    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
  });
}

async function saveCachedGraph(repoKey, graphData) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.put(graphData, repoKey);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve();
  });
}

async function loadCachedGraph(repoKey) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.get(repoKey);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result || null);
  });
}

async function deleteCachedGraph(repoKey) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.delete(repoKey);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve();
  });
}

// localStorage hash operations
function saveCachedHashes(repoKey, hashMap) {
  const key = HASH_PREFIX + repoKey;
  localStorage.setItem(key, JSON.stringify(hashMap));
}

function loadCachedHashes(repoKey) {
  const key = HASH_PREFIX + repoKey;
  const raw = localStorage.getItem(key);
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function deleteCachedHashes(repoKey) {
  const key = HASH_PREFIX + repoKey;
  localStorage.removeItem(key);
}

// Combined operations
async function saveCache(repoKey, graphData, hashMap) {
  await saveCachedGraph(repoKey, graphData);
  saveCachedHashes(repoKey, hashMap);
}

async function loadCache(repoKey) {
  const [graphData, hashMap] = await Promise.all([
    loadCachedGraph(repoKey),
    Promise.resolve(loadCachedHashes(repoKey)),
  ]);
  return { graphData, hashMap };
}

async function deleteCache(repoKey) {
  await deleteCachedGraph(repoKey);
  deleteCachedHashes(repoKey);
}

// Hash computation
async function computeHash(content) {
  const encoder = new TextEncoder();
  const data = encoder.encode(content);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

// Export for use in explorer.js and generate-graph.js
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    getRepoKey,
    saveCachedGraph,
    loadCachedGraph,
    deleteCachedGraph,
    saveCachedHashes,
    loadCachedHashes,
    deleteCachedHashes,
    saveCache,
    loadCache,
    deleteCache,
    computeHash,
  };
}

// Graph diffing and patching for incremental sync
// Compares file hashes, identifies changed files, patches graphData

function diffHashes(oldMap, newMap) {
  const added = [];
  const changed = [];
  const removed = [];
  const unchanged = [];

  for (const [path, newHash] of Object.entries(newMap)) {
    const oldHash = oldMap[path];
    if (!oldHash) {
      added.push({ path, hash: newHash });
    } else if (oldHash !== newHash) {
      changed.push({ path, oldHash, newHash });
    } else {
      unchanged.push({ path, hash: newHash });
    }
  }

  for (const [path, oldHash] of Object.entries(oldMap)) {
    if (!newMap[path]) {
      removed.push({ path, hash: oldHash });
    }
  }

  return { added, changed, removed, unchanged };
}

function patchGraph(graphData, changedFiles, newNodes, newEdges, newSymbolEdges) {
  const changedPaths = new Set(changedFiles.map(f => f.path));

  // Remove old nodes/edges for changed files
  graphData.nodes = graphData.nodes.filter(n => !changedPaths.has(n.id));
  graphData.edges = graphData.edges.filter(e => 
    !changedPaths.has(e.from) && !changedPaths.has(e.to)
  );
  graphData.symbolEdges = graphData.symbolEdges.filter(e => 
    !changedPaths.has(e.fromFile) && !changedPaths.has(e.toFile)
  );

  // Add new nodes/edges for changed files
  graphData.nodes.push(...newNodes);
  graphData.edges.push(...newEdges);
  graphData.symbolEdges.push(...newSymbolEdges);

  return graphData;
}

function buildHashMapFromGraph(graphData) {
  const map = {};
  for (const node of graphData.nodes) {
    if (node.hash) {
      map[node.id] = node.hash;
    }
  }
  return map;
}

// Export for use in explorer.js and generate-graph.js
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    diffHashes,
    patchGraph,
    buildHashMapFromGraph,
  };
}

// @ts-check
// ============================================================
// CLIENT-SIDE GRAPH GENERATOR — uses GitHub API, no server needed
// ============================================================

/** @typedef {import('./types/graph-contract').GraphData} GraphData */

// DEV MODE: Set to true to use hardcoded token for testing
const DEV_MODE = false;
const DEV_GITHUB_TOKEN = 'YOUR_GITHUB_TOKEN_HERE';

const EXCLUDED_DIRS = new Set([
  'node_modules', '__pycache__', '.git', 'build', 'dist',
  'vendor', '.venv', 'venv', 'env', '.tox', '.mypy_cache',
  'target', 'bin', 'obj', '.gradle', '.idea', '.vscode',
  'coverage', '.next', '.nuxt', '.cache',
]);
const EXCLUDED_FILES = new Set(['package-lock.json', 'yarn.lock', 'pnpm-lock.yaml']);

const LANG_CONFIG = {
  '.js':   'javascript', '.mjs':  'javascript', '.jsx':  'javascript',
  '.ts':   'typescript', '.tsx':  'typescript',
  '.py':   'python', '.go': 'go', '.java': 'java', '.rs': 'rust',
  '.cs':   'csharp', '.rb': 'ruby', '.php': 'php', '.swift': 'swift',
  '.kt':   'kotlin', '.scala': 'scala', '.c': 'c', '.cpp': 'cpp',
  '.h':    'c', '.hpp': 'cpp',
  '.html': 'html', '.htm': 'html', '.css': 'css', '.scss': 'css', '.less': 'css',
  '.vue':  'vue', '.svelte': 'svelte',
  '.json': 'json', '.yaml': 'yaml', '.yml': 'yaml',
  '.md':   'markdown', '.sh': 'shell', '.bash': 'shell',
  '.sql':  'sql', '.xml': 'xml', '.toml': 'toml', '.env': 'env',
  '.dockerfile': 'docker',
};

const FILENAME_LANG = {
  'Dockerfile': 'docker', 'Makefile': 'shell', 'Jenkinsfile': 'shell',
  '.gitignore': 'env', '.dockerignore': 'env', '.editorconfig': 'env',
  '.eslintrc': 'json', '.prettierrc': 'json',
};

const BINARY_EXTENSIONS = new Set([
  '.png', '.jpg', '.jpeg', '.gif', '.bmp', '.ico', '.svg', '.webp',
  '.mp3', '.mp4', '.wav', '.avi', '.mov', '.mkv', '.flac',
  '.zip', '.tar', '.gz', '.rar', '.7z', '.bz2',
  '.pdf', '.doc', '.docx', '.xls', '.xlsx', '.ppt', '.pptx',
  '.woff', '.woff2', '.ttf', '.eot', '.otf',
  '.exe', '.dll', '.so', '.dylib', '.o', '.a',
  '.lock', '.map',
]);

const PARTIAL_PARSE_LANGS = new Set(['json', 'yaml', 'markdown', 'xml', 'toml', 'env', 'docker', 'sql']);
const PARSE_STATUS_FULL = 'full';
const PARSE_STATUS_PARTIAL = 'partial';
const PARSE_STATUS_UNSUPPORTED = 'unsupported';

// ============================================================
// LOCAL FOLDER LOADING (File System Access API)
// ============================================================
async function walkLocalFolder(rootHandle, onProgress) {
  if (!rootHandle) {
    throw new Error('walkLocalFolder requires a directory handle');
  }
  if (rootHandle.kind !== 'directory') {
    throw new Error('walkLocalFolder expected a directory handle');
  }

  const files = [];
  const stack = [{ handle: rootHandle, path: '' }];
  let visited = 0;

  while (stack.length > 0) {
    const { handle, path } = stack.pop();
    for await (const entry of handle.values()) {
      if (entry.kind === 'directory') {
        if (EXCLUDED_DIRS.has(entry.name) || entry.name.startsWith('.')) {
          continue;
        }
        const nextPath = path ? `${path}/${entry.name}` : entry.name;
        stack.push({ handle: entry, path: nextPath });
      } else if (entry.kind === 'file') {
        if (EXCLUDED_FILES.has(entry.name)) {
          continue;
        }
        const nextPath = path ? `${path}/${entry.name}` : entry.name;
        const ext = entry.name.includes('.') ? '.' + entry.name.split('.').pop().toLowerCase() : '';
        const lang = LANG_CONFIG[ext] || FILENAME_LANG[entry.name];
        const file = await entry.getFile();
        if (lang) {
          files.push({ handle: entry, path: nextPath, size: file.size, lang, ext });
        } else if (!entry.name.startsWith('.') && (ext === '' || !BINARY_EXTENSIONS.has(ext))) {
          const unknownFile = { handle: entry, path: nextPath, size: file.size, lang: 'unknown', ext };
          if (ext) {
            unknownFile.unsupportedExt = ext;
          }
          files.push(unknownFile);
        }
        visited++;
        if (onProgress && visited % 50 === 0) {
          onProgress(`Scanning local folder... ${visited} items`);
          await new Promise((r) => setTimeout(r, 0));
        }
      }
    }
  }

  return files;
}

// ============================================================
// GITHUB API
// ============================================================
function parseGitHubUrl(url) {
  const match = url.match(/github\.com\/([^/]+)\/([^/]+)/);
  if (!match) return null;
  return { owner: match[1], repo: match[2].replace(/\.git$/, '') };
}

// ============================================================
// GITLAB API
// ============================================================
function parseGitLabUrl(url) {
  const idx = url.indexOf('gitlab.com/');
  if (idx === -1) return null;
  const after = url.substring(idx + 'gitlab.com/'.length);
  const cleaned = after.replace(/^\/+/, '').replace(/\.git$/, '').replace(/\/+$/, '');
  if (!cleaned) return null;
  const parts = cleaned.split('/').filter(Boolean);
  if (parts.length < 2) return null;
  const namespacePath = parts.join('/');
  const projectId = encodeURIComponent(namespacePath);
  return { namespacePath, projectId };
}

async function fetchGitLabProject(projectId, token) {
  if (!token) {
    throw new Error('GitLab token is required to fetch project metadata');
  }
  const headers = { 'Accept': 'application/json', 'Authorization': `Bearer ${token}` };
  const res = await fetch(`https://gitlab.com/api/v4/projects/${projectId}`, { headers });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`GitLab project fetch failed: ${res.status} ${text}`);
  }
  const data = await res.json();
  if (!data || !data.default_branch || !data.path_with_namespace) {
    throw new Error('GitLab project response missing default_branch or path_with_namespace');
  }
  return { defaultBranch: data.default_branch, pathWithNamespace: data.path_with_namespace, headers };
}

async function fetchGitLabTree(projectId, branch, headers) {
  const all = [];
  let page = 1;
  const perPage = 100;
  while (true) {
    const url = new URL(`https://gitlab.com/api/v4/projects/${projectId}/repository/tree`);
    url.searchParams.set('ref', branch);
    url.searchParams.set('recursive', 'true');
    url.searchParams.set('per_page', String(perPage));
    url.searchParams.set('page', String(page));

    const res = await fetch(url.toString(), { headers });
    if (!res.ok) {
      const text = await res.text();
      throw new Error(`GitLab tree fetch failed: ${res.status} ${text}`);
    }
    const data = await res.json();
    if (!Array.isArray(data)) {
      throw new Error('GitLab tree response is not an array');
    }
    all.push(...data);

    const nextPage = res.headers.get('x-next-page');
    if (!nextPage) {
      break;
    }
    page = Number(nextPage);
    if (!Number.isFinite(page) || page <= 0) {
      throw new Error('GitLab pagination header x-next-page is invalid');
    }
  }
  return all;
}

async function fetchGitLabFileRaw(projectId, branch, filePath, headers) {
  const encodedPath = encodeURIComponent(filePath);
  const url = `https://gitlab.com/api/v4/projects/${projectId}/repository/files/${encodedPath}/raw?ref=${encodeURIComponent(branch)}`;
  const res = await fetch(url, { headers });
  if (!res.ok) return null;
  return await res.text();
}

async function fetchGitHubTree(owner, repo, token) {
  const headers = { 'Accept': 'application/vnd.github.v3+json' };
  const effectiveToken = token || (DEV_MODE ? DEV_GITHUB_TOKEN : null);
  if (effectiveToken) headers['Authorization'] = `token ${effectiveToken}`;

  // Get default branch
  const repoRes = await fetch(`https://api.github.com/repos/${owner}/${repo}`, { headers });
  if (!repoRes.ok) {
    const err = await repoRes.json();
    throw new Error(err.message || `GitHub API error: ${repoRes.status}`);
  }
  const repoData = await repoRes.json();
  const branch = repoData.default_branch;

  // Get full tree
  const treeRes = await fetch(`https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`, { headers });
  if (!treeRes.ok) {
    const err = await treeRes.json();
    throw new Error(err.message || `GitHub tree error: ${treeRes.status}`);
  }
  const treeData = await treeRes.json();
  if (treeData.truncated) {
    console.warn('Tree was truncated — very large repo');
  }
  return { tree: treeData.tree, branch, headers };
}

async function fetchFileContent(owner, repo, filePath, headers) {
  const url = `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}`;
  const res = await fetch(url, { headers });
  if (!res.ok) return null;
  const data = await res.json();
  if (data.encoding !== 'base64') {
    return null;
  }
  if (!data.content) {
    throw new Error('GitHub contents API returned base64 encoding but no content');
  }

  const b64 = data.content.replace(/\n/g, '');
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new TextDecoder('utf-8').decode(bytes);
}

async function fetchLastCommitDate(owner, repo, filePath, headers) {
  const url = `https://api.github.com/repos/${owner}/${repo}/commits?path=${encodeURIComponent(filePath)}&per_page=1`;
  const res = await fetch(url, { headers });
  if (!res.ok) return null;
  const data = await res.json();
  if (!Array.isArray(data) || data.length === 0 || !data[0].commit || !data[0].commit.committer) {
    return null;
  }
  return data[0].commit.committer.date || null;
}

async function fetchCommitDatesForRepo(repoFull, token, files, onProgress) {
  const parts = repoFull.split('/');
  if (parts.length !== 2) {
    throw new Error('Invalid repo format for commit fetch. Expected owner/repo.');
  }
  const owner = parts[0];
  const repo = parts[1];
  const headers = { 'Accept': 'application/vnd.github.v3+json' };
  const effectiveToken = token || (DEV_MODE ? DEV_GITHUB_TOKEN : null);
  if (effectiveToken) headers['Authorization'] = `token ${effectiveToken}`;

  const commitDates = {};
  let processed = 0;
  for (const file of files) {
    const date = await fetchLastCommitDate(owner, repo, file.path, headers);
    if (date) {
      commitDates[file.path] = date;
    }
    processed++;
    if (onProgress) onProgress(`Commit dates ${processed}/${files.length}`);
  }

  return commitDates;
}

async function fetchBlameForRepo(repoFull, token, files, onProgress) {
  const parts = repoFull.split('/');
  if (parts.length !== 2) {
    throw new Error('Invalid repo format for blame fetch. Expected owner/repo.');
  }
  const owner = parts[0];
  const repo = parts[1];
  const headers = { 'Accept': 'application/vnd.github.v3+json' };
  if (token) headers['Authorization'] = `token ${token}`;

  const blameData = {};
  let processed = 0;
  for (const file of files) {
    const url = `https://api.github.com/repos/${owner}/${repo}/commits?path=${encodeURIComponent(file.path)}&per_page=1`;
    const res = await fetch(url, { headers });
    if (res.ok) {
      const data = await res.json();
      if (Array.isArray(data) && data.length > 0 && data[0].commit) {
        const authorObj = data[0].commit.author || data[0].commit.committer;
        if (!authorObj || !authorObj.name || !authorObj.date) {
          throw new Error(`Invalid author data returned for ${file.path}`);
        }
        blameData[file.path] = {
          author: authorObj.name,
          email: authorObj.email || '',
          date: authorObj.date,
        };
      }
    }
    processed++;
    if (onProgress) onProgress(`Blame ${processed}/${files.length}`);
  }
  return blameData;
}

// ============================================================
// FILE FILTERING
// ============================================================
function filterTree(tree) {
  const files = [];
  const skippedExts = new Set();

  for (const item of tree) {
    if (item.type !== 'blob') continue;
    const parts = item.path.split('/');
    const fileName = parts[parts.length - 1];

    // Check excluded dirs
    let excluded = false;
    for (let i = 0; i < parts.length - 1; i++) {
      if (EXCLUDED_DIRS.has(parts[i]) || parts[i].startsWith('.')) {
        excluded = true;
        break;
      }
    }
    if (excluded) continue;
    if (EXCLUDED_FILES.has(fileName)) continue;

    const ext = fileName.includes('.') ? '.' + fileName.split('.').pop().toLowerCase() : '';
    const lang = LANG_CONFIG[ext] || FILENAME_LANG[fileName];

    if (lang) {
      files.push({ path: item.path, size: item.size || 0, lang });
    } else if (!fileName.startsWith('.') && (ext === '' || !BINARY_EXTENSIONS.has(ext))) {
      // Fallback: include unsupported text files as plain nodes (no imports/defs)
      files.push({ path: item.path, size: item.size || 0, lang: 'unknown', ext });
      if (ext) {
        skippedExts.add(ext);
      }
    }
  }

  return { files, skippedExts };
}

// ============================================================
// IMPORT EXTRACTION
// ============================================================
function extractImports(content, lang) {
  const imports = new Set();
  const patterns = {
    javascript: [
      /require\s*\(\s*['"]([^'"]+)['"]\s*\)/g,
      /import\s+.*?from\s+['"]([^'"]+)['"]/g,
      /import\s+['"]([^'"]+)['"]/g,
    ],
    typescript: [
      /import\s+.*?from\s+['"]([^'"]+)['"]/g,
      /import\s+['"]([^'"]+)['"]/g,
      /require\s*\(\s*['"]([^'"]+)['"]\s*\)/g,
    ],
    python: [/^\s*import\s+(\S+)/gm, /^\s*from\s+(\S+)\s+import/gm],
    go: [/^\s*"([^"]+)"/gm],
    java: [/^\s*import\s+(?:static\s+)?([a-zA-Z0-9_.]+)/gm],
    rust: [/^\s*use\s+([a-zA-Z0-9_:]+)/gm],
    csharp: [/^\s*using\s+(?:static\s+)?([a-zA-Z0-9_.]+)/gm],
    ruby: [/^\s*require\s+['"]([^'"]+)['"]/gm, /^\s*require_relative\s+['"]([^'"]+)['"]/gm],
    php: [/^\s*(?:use|include|require)\s+['"]?([^'";]+)/gm],
    swift: [/^\s*import\s+(\S+)/gm],
    kotlin: [/^\s*import\s+([a-zA-Z0-9_.]+)/gm],
    scala: [/^\s*import\s+([a-zA-Z0-9_.{}]+)/gm],
    c: [/^\s*#include\s+["<]([^">]+)[">]/gm],
    cpp: [/^\s*#include\s+["<]([^">]+)[">]/gm],
    html: [/<script\s+[^>]*src=["']([^"']+)["']/gi, /<link\s+[^>]*href=["']([^"']+)["']/gi],
    css: [/@import\s+(?:url\s*\(\s*)?['"]?([^'");\s]+)['"]?\s*\)?\s*;/gm],
    vue: [/import\s+.*?from\s+['"]([^'"]+)['"]/g],
    svelte: [/import\s+.*?from\s+['"]([^'"]+)['"]/g],
    shell: [/^\s*(?:source|\.)\s+['"]?([^'";\s]+)['"]?/gm],
    sql: [], json: [], yaml: [], markdown: [], xml: [], toml: [], env: [], docker: [],
