      [/^\s*CREATE\s+(?:OR\s+REPLACE\s+)?TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?(?:`|")?([a-zA-Z_][a-zA-Z0-9_]*)(?:`|")?/gim, 'class'],
      [/^\s*CREATE\s+(?:OR\s+REPLACE\s+)?(?:FUNCTION|PROCEDURE)\s+(?:`|")?([a-zA-Z_][a-zA-Z0-9_]*)(?:`|")?/gim, 'function'],
