  const langPatterns = patterns[lang];
  if (!langPatterns) return defs;
  for (const [pattern, kind] of langPatterns) {
    let match;
    while ((match = pattern.exec(content)) !== null) {
      const name = match[1];
      if (!seen.has(name) && !SKIP_KEYWORDS.has(name) && name.length > 1) {
