function escapeRegexLiteral(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function buildSymbolMatchers(names) {
  return names.map((name) => {
    const escaped = escapeRegexLiteral(name);
    return {
      name,
      call: new RegExp(`(^|[^\\w$])(?:new\\s+)?${escaped}\\s*\\(`),
      usage: new RegExp(`(^|[^\\w$])${escaped}([^\\w$]|$)`),
      declaration: new RegExp(`\\b(function|class|const|let|var|type|interface|enum|def|fn|func)\\s+${escaped}\\b`),
    };
  });
}

function extractSymbolReferences(content, knownDefinitions) {
  if (typeof content !== 'string' || content.length === 0 || !Array.isArray(knownDefinitions)) return [];
  const names = [...new Set(knownDefinitions.map((def) => def.name).filter(Boolean))];
  if (names.length === 0) return [];
  const refs = [];
  const seen = new Set();
  const matchers = buildSymbolMatchers(names);
  const lines = content.split('\n');

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    for (const matcher of matchers) {
      if (matcher.declaration.test(line)) continue;
      if (!matcher.call.test(line) && !matcher.usage.test(line)) continue;
      const key = `${matcher.name}@${i + 1}`;
      if (seen.has(key)) continue;
      seen.add(key);
      refs.push({ name: matcher.name, line: i + 1 });
    }
  }
  return refs;
}

function findContainingDefinition(definitions, line) {
  if (!Array.isArray(definitions) || definitions.length === 0) return null;
  const sorted = [...definitions].sort((a, b) => a.line - b.line);
  let nearest = null;
  let nearestFunction = null;

  for (const def of sorted) {
    if (def.line > line) break;
    nearest = def;
    if (def.kind === 'function') nearestFunction = def;
  }
  return nearestFunction || nearest;
}

function buildSymbolDefinitionIndex(nodes) {
  const symbolIndex = new Map();
  for (const node of nodes) {
    for (const def of node.definitions || []) {
      if (!symbolIndex.has(def.name)) symbolIndex.set(def.name, []);
      symbolIndex.get(def.name).push({ file: node.id, def });
    }
  }
  return symbolIndex;
}

function buildDefinitionsByFile(nodes) {
  const definitionsByFile = new Map();
  for (const node of nodes) {
    definitionsByFile.set(node.id, node.definitions || []);
  }
  return definitionsByFile;
}

function buildReferenceCandidates(fileId, definitionsByFile, importsByFile) {
  const byName = new Map();
  const addDefs = (defs) => {
    for (const def of defs || []) {
      if (!def || !def.name || byName.has(def.name)) continue;
      byName.set(def.name, def);
    }
  };

  addDefs(definitionsByFile.get(fileId));
  for (const importedFile of importsByFile.get(fileId) || []) {
    addDefs(definitionsByFile.get(importedFile));
  }
  return Array.from(byName.values());
}

function resolveSymbolTargets(fromFile, refName, symbolIndex, importsByFile) {
  const candidates = symbolIndex.get(refName) || [];
  if (candidates.length === 0) return [];
  const sameFile = candidates.filter((candidate) => candidate.file === fromFile);
  if (sameFile.length > 0) return sameFile;
  const importedFiles = importsByFile.get(fromFile) || new Set();
  return candidates.filter((candidate) => importedFiles.has(candidate.file));
}

function addSymbolEdge(symbolEdges, seen, fromFile, sourceDef, target, callLine) {
  if (fromFile === target.file && sourceDef.name === target.def.name) return;
  const key = `${fromFile}|${sourceDef.name}|${target.file}|${target.def.name}|${callLine}`;
  if (seen.has(key)) return;
  seen.add(key);
  symbolEdges.push({
    fromFile,
    toFile: target.file,
    fromSymbol: sourceDef.name,
    toSymbol: target.def.name,
    fromKind: sourceDef.kind || 'function',
    toKind: target.def.kind || 'function',
    fromLine: sourceDef.line || 0,
    toLine: target.def.line || 0,
    callLine,
    type: 'static-call',
  });
}

function buildSymbolEdges(nodes, importsByFile, refsByFile) {
  const symbolEdges = [];
  const seen = new Set();
  const symbolIndex = buildSymbolDefinitionIndex(nodes);
  const definitionsByFile = buildDefinitionsByFile(nodes);

  for (const node of nodes) {
    const content = refsByFile.get(node.id) || '';
    const candidates = buildReferenceCandidates(node.id, definitionsByFile, importsByFile);
    if (candidates.length === 0) continue;
    const refs = extractSymbolReferences(content, candidates);
    const definitions = node.definitions || [];
    for (const ref of refs) {
      const sourceDef = findContainingDefinition(definitions, ref.line);
      if (!sourceDef) continue;
      const targets = resolveSymbolTargets(node.id, ref.name, symbolIndex, importsByFile);
      for (const target of targets) {
        addSymbolEdge(symbolEdges, seen, node.id, sourceDef, target, ref.line);
      }
    }
  }
  return symbolEdges;
}

// ============================================================
// IMPORT RESOLUTION (path-based, relative only)
// ============================================================
function resolveImport(importPath, fromFile, fileSet, lang) {
  if (lang === 'python') {
    const pyPath = importPath.replace(/\./g, '/');
    const fromDir = fromFile.substring(0, fromFile.lastIndexOf('/'));
    const candidates = [
      pyPath + '.py', pyPath + '/__init__.py',
      fromDir + '/' + pyPath + '.py', fromDir + '/' + pyPath + '/__init__.py',
    ];
    for (const c of candidates) {
      const normalized = normalizePath(c);
      if (fileSet.has(normalized)) return normalized;
    }
    return null;
  }

  if (lang === 'javascript' || lang === 'typescript') {
    if (!importPath.startsWith('.') && !importPath.startsWith('/')) return null;
    const fromDir = fromFile.substring(0, fromFile.lastIndexOf('/'));
    const resolved = normalizePath(fromDir + '/' + importPath);
    const exts = lang === 'typescript'
      ? ['', '.ts', '.tsx', '.js', '.jsx', '/index.ts', '/index.tsx', '/index.js']
      : ['', '.js', '.mjs', '.jsx', '/index.js'];
    for (const ext of exts) {
      if (fileSet.has(resolved + ext)) return resolved + ext;
    }
    return null;
  }

  if (lang === 'ruby') {
    if (!importPath.startsWith('.')) return null;
    const fromDir = fromFile.substring(0, fromFile.lastIndexOf('/'));
    const resolved = normalizePath(fromDir + '/' + importPath);
    if (fileSet.has(resolved)) return resolved;
    if (fileSet.has(resolved + '.rb')) return resolved + '.rb';
    return null;
  }

  if (lang === 'c' || lang === 'cpp') {
    if (importPath.startsWith('<')) return null;
    const fromDir = fromFile.substring(0, fromFile.lastIndexOf('/'));
    const resolved = normalizePath(fromDir + '/' + importPath);
    if (fileSet.has(resolved)) return resolved;
    return null;
  }

  if (lang === 'html' || lang === 'css' || lang === 'vue' || lang === 'svelte') {
    if (importPath.startsWith('http://') || importPath.startsWith('https://') || importPath.startsWith('//')) return null;
    const fromDir = fromFile.substring(0, fromFile.lastIndexOf('/'));
    const resolved = normalizePath(fromDir + '/' + importPath);
    if (fileSet.has(resolved)) return resolved;
    return null;
  }

  return null;
}

function normalizePath(p) {
  const parts = [];
  for (const seg of p.split('/')) {
    if (seg === '..') { parts.pop(); }
    else if (seg !== '.' && seg !== '') { parts.push(seg); }
  }
  return parts.join('/');
}

function buildPreviewLines(content, maxLines = 8) {
  if (typeof content !== 'string' || content.length === 0) {
    return [];
  }
  return content
    .split('\n')
    .filter((line) => line.trim().length > 0)
    .slice(0, maxLines)
    .map((line) => (line.length > 120 ? line.substring(0, 120) + '...' : line));
}

function buildRawPreview(content, maxLines = 3) {
  if (typeof content !== 'string' || content.length === 0) {
    return [];
  }
  return content
    .split('\n')
    .slice(0, maxLines)
    .map((line) => (line.length > 180 ? line.substring(0, 180) + '...' : line));
}

function getParseProfile(file, content) {
  const lang = file.lang || 'unknown';
  const hasContent = typeof content === 'string' && content.length > 0;

  if (lang === 'unknown') {
    const extLabel = file.ext || 'unknown extension';
    return {
      parseStatus: PARSE_STATUS_UNSUPPORTED,
      parseReason: `No parser configured for ${extLabel}`,
    };
  }

  if (!hasContent) {
    return {
      parseStatus: PARSE_STATUS_PARTIAL,
      parseReason: 'Source content unavailable; showing file metadata only',
    };
  }

  if (PARTIAL_PARSE_LANGS.has(lang)) {
    return {
      parseStatus: PARSE_STATUS_PARTIAL,
      parseReason: `Lightweight parser mode for ${lang}`,
    };
  }

  return {
    parseStatus: PARSE_STATUS_FULL,
    parseReason: `Parser active for ${lang}`,
  };
}

function buildNodeFromContent(file, content) {
  const lang = file.lang || 'unknown';
  const safeContent = typeof content === 'string' ? content : '';
  const allLines = safeContent.length > 0 ? safeContent.split('\n') : [];
  const parts = file.path.split('/');
  const folder = parts.length > 1 ? parts[0] : '_root';
  const previewLines = buildPreviewLines(safeContent);
  const { parseStatus, parseReason } = getParseProfile(file, safeContent);

  const definitions = parseStatus === PARSE_STATUS_UNSUPPORTED || safeContent.length === 0
    ? []
    : extractDefinitions(safeContent, lang);
  const imports = parseStatus === PARSE_STATUS_UNSUPPORTED || safeContent.length === 0
    ? new Set()
    : extractImports(safeContent, lang);

  return {
    node: {
      id: file.path,
      label: parts[parts.length - 1],
      folder,
      lines: allLines.length,
      fullPath: file.path,
      definitions,
      lang,
      preview: previewLines,
      rawPreview: buildRawPreview(safeContent),
      content: safeContent,
      parseStatus,
      parseReason,
      size: file.size || 0,
    },
    imports,
    parseStatus,
    lang,
  };
}

// Per-file parsing for incremental sync
async function parseFile(file, content) {
  const { node, imports, parseStatus, lang } = buildNodeFromContent(file, content);
  const refs = typeof content === 'string' ? content : '';
  return { node, imports: Array.from(imports), refs, parseStatus, lang };
}

// ============================================================
// MAIN: generateGraphFromGitHub
// ============================================================
/** @returns {Promise<GraphData>} */
async function generateGraphFromGitHub(githubUrl, token, onProgress) {
  const parsed = parseGitHubUrl(githubUrl);
  if (!parsed) throw new Error('Invalid GitHub URL. Use: https://github.com/owner/repo');

  const effectiveToken = token || (DEV_MODE ? DEV_GITHUB_TOKEN : null);

  if (onProgress) onProgress('Fetching repository tree...');
  const { tree, branch, headers } = await fetchGitHubTree(parsed.owner, parsed.repo, effectiveToken);

  const { files, skippedExts } = filterTree(tree);
  if (files.length === 0) throw new Error('No source files found in this repo after filters');

  if (onProgress) onProgress(`Found ${files.length} files. Fetching contents...`);

  const fileSet = new Set(files.map(f => f.path));
  const nodes = [];
  const edges = [];
  const importsByFile = new Map();
  const refsByFile = new Map();
  /** @type {Record<string, number>} */
  const langStats = {};
  const parseSummary = {
    [PARSE_STATUS_FULL]: 0,
    [PARSE_STATUS_PARTIAL]: 0,
    [PARSE_STATUS_UNSUPPORTED]: 0,
  };

  // Batch fetch — up to 20 concurrent
  const BATCH_SIZE = 20;
  let fetched = 0;

  for (let i = 0; i < files.length; i += BATCH_SIZE) {
    const batch = files.slice(i, i + BATCH_SIZE);
    const results = await Promise.all(
      batch.map(async (file) => {
        const content = await fetchFileContent(parsed.owner, parsed.repo, file.path, headers);
        return { file, content };
      })
    );

    for (const { file, content } of results) {
      fetched++;
      const { node, imports, parseStatus, lang } = buildNodeFromContent(file, content);
      langStats[lang] = (langStats[lang] || 0) + 1;
      parseSummary[parseStatus] = (parseSummary[parseStatus] || 0) + 1;
      nodes.push(node);
      refsByFile.set(file.path, content || '');

      const resolvedImports = new Set();
      for (const imp of imports) {
        const resolved = resolveImport(imp, file.path, fileSet, lang);
        if (!resolved) continue;
        edges.push({ from: file.path, to: resolved });
        resolvedImports.add(resolved);
      }
      importsByFile.set(file.path, resolvedImports);
    }

    if (onProgress) onProgress(`Analyzed ${fetched}/${files.length} files...`);
  }

  const symbolEdges = buildSymbolEdges(nodes, importsByFile, refsByFile);

  /** @type {GraphData} */
  const graphData = {
    nodes,
    edges,
    symbolEdges,
    meta: {
      languages: langStats,
      parseSummary,
      unsupportedExtensions: Array.from(skippedExts).sort(),
      totalFiles: files.length,
      generatedAt: new Date().toISOString(),
      repo: `${parsed.owner}/${parsed.repo}`,
      branch,
      provider: 'github',
    },
  };
  return graphData;
}

// ============================================================
// MAIN: generateGraphFromLocalFolder
// ============================================================
/** @returns {Promise<GraphData>} */
async function generateGraphFromLocalFolder(directoryHandle, onProgress) {
  if (!directoryHandle) {
    throw new Error('generateGraphFromLocalFolder requires a directory handle');
  }
  if (directoryHandle.kind !== 'directory') {
    throw new Error('generateGraphFromLocalFolder expected a directory handle');
  }

  if (onProgress) onProgress('Scanning local folder...');
  const rawEntries = await walkLocalFolder(directoryHandle, onProgress);
  if (!Array.isArray(rawEntries)) {
    throw new Error('Local folder scan failed to return file entries');
  }

  const files = rawEntries;
  /** @typedef {{ handle: FileSystemFileHandle, path: string, size: number, lang: string, ext: string, unsupportedExt?: string }} LocalFileEntry */
  /** @type {LocalFileEntry[]} */
  const typedEntries = rawEntries;
  const unsupportedExts = new Set(
    typedEntries.filter((f) => f.lang === 'unknown' && f.unsupportedExt).map((f) => f.unsupportedExt)
  );

  if (files.length === 0) {
    throw new Error('No source files found in this folder after filters');
  }

  if (onProgress) onProgress(`Found ${files.length} files. Reading contents...`);

  const fileSet = new Set(files.map((f) => f.path));
  const nodes = [];
  const edges = [];
  const importsByFile = new Map();
  const refsByFile = new Map();
  /** @type {Record<string, number>} */
  const langStats = {};
  const parseSummary = {
    [PARSE_STATUS_FULL]: 0,
    [PARSE_STATUS_PARTIAL]: 0,
    [PARSE_STATUS_UNSUPPORTED]: 0,
  };

  const BATCH_SIZE = 20;
  let processed = 0;

  for (let i = 0; i < files.length; i += BATCH_SIZE) {
    const batch = files.slice(i, i + BATCH_SIZE);
    const results = await Promise.all(
      batch.map(async (file) => {
        try {
          const blob = await file.handle.getFile();
          const content = await blob.text();
          return { file, content };
        } catch (e) {
          console.error('Local file read failed:', file.path, e.message);
          return { file, content: '' };
        }
      })
    );

    for (const { file, content } of results) {
      processed++;
      const { node, imports, parseStatus, lang } = buildNodeFromContent(file, content);
      langStats[lang] = (langStats[lang] || 0) + 1;
      parseSummary[parseStatus] = (parseSummary[parseStatus] || 0) + 1;
      nodes.push(node);
      refsByFile.set(file.path, content || '');

      const resolvedImports = new Set();
      for (const imp of imports) {
        const resolved = resolveImport(imp, file.path, fileSet, lang);
        if (!resolved) continue;
        edges.push({ from: file.path, to: resolved });
        resolvedImports.add(resolved);
      }
      importsByFile.set(file.path, resolvedImports);
    }

    if (onProgress) onProgress(`Analyzed ${processed}/${files.length} files...`);
    await new Promise((r) => setTimeout(r, 0));
  }

  const symbolEdges = buildSymbolEdges(nodes, importsByFile, refsByFile);

  /** @type {GraphData} */
  const graphData = {
    nodes,
    edges,
    symbolEdges,
    meta: {
      languages: langStats,
      parseSummary,
      unsupportedExtensions: Array.from(unsupportedExts).sort(),
      totalFiles: files.length,
      generatedAt: new Date().toISOString(),
      repo: directoryHandle.name,
      branch: 'local',
      provider: 'local',
    },
  };
  return graphData;
}

