// ============================================================
// LLM PROVIDER - Ollama Integration
// ============================================================

class LLMProvider {
    constructor(baseUrl, model = 'llama3.2') {
        if (!baseUrl) {
            throw new Error('LLMProvider: baseUrl is required');
        }
        this.baseUrl = baseUrl.replace(/\/$/, '');
        this.model = model;
        this.timeout = 30000;
    }

    async chat(messages, options = {}) {
        const url = `${this.baseUrl}/api/chat`;
        const payload = {
            model: options.model || this.model,
            messages: messages,
            stream: false,
            options: {
                temperature: options.temperature ?? 0.7,
                num_predict: options.num_predict ?? 2048,
            }
        };

        try {
            const response = await fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
                signal: AbortSignal.timeout(this.timeout)
            });

            if (!response.ok) {
                throw new Error(`LLMProvider: HTTP ${response.status} from ${url}`);
            }

            const data = await response.json();
            return data.message?.content || '';
        } catch (error) {
            if (error.name === 'TimeoutError') {
                throw new Error(`LLMProvider: Request timeout after ${this.timeout}ms`);
            }
            throw new Error(`LLMProvider: ${error.message}`);
        }
    }

    async generate(prompt, options = {}) {
        const messages = [{ role: 'user', content: prompt }];
        return this.chat(messages, options);
    }

    setModel(model) {
        if (!model) {
            throw new Error('LLMProvider: model name is required');
        }
        this.model = model;
    }

    setTimeout(ms) {
        if (typeof ms !== 'number' || ms <= 0) {
            throw new Error('LLMProvider: timeout must be positive number');
        }
        this.timeout = ms;
    }
}

module.exports = { LLMProvider };

// ============================================================
// CodeFly Multiplayer — Cloudflare Durable Objects
// Each repo URL = one Room Durable Object
// ============================================================

export { Room } from './room.js';

export default {
    async fetch(request, env) {
        const url = new URL(request.url);

        // CORS preflight
        if (request.method === 'OPTIONS') {
            return new Response(null, {
                headers: {
                    'Access-Control-Allow-Origin': '*',
                    'Access-Control-Allow-Methods': 'GET, OPTIONS',
                    'Access-Control-Allow-Headers': 'Content-Type',
                },
            });
        }

        // Route: /room/:roomId  (WebSocket upgrade)
        const match = url.pathname.match(/^\/room\/(.+)$/);
        if (!match) {
            return new Response('CodeFly Multiplayer — connect via /room/:repoUrl', { status: 200 });
        }

        const roomId = decodeURIComponent(match[1]);
        const roomObjectId = env.ROOMS.idFromName(roomId);
        const roomObject = env.ROOMS.get(roomObjectId);

        return roomObject.fetch(request);
    },
};

// ============================================================
// Room Durable Object — one instance per repo URL
// Handles WebSocket connections, presence broadcast, chat
// ============================================================

const PRESENCE_THROTTLE_MS = 80;

export class Room {
    constructor(state, env) {
        this.state = state;
        this.env = env;
        this.sessions = new Map(); // connId -> { ws, presence }
        this.lastBroadcast = 0;
    }

    async fetch(request) {
        const upgradeHeader = request.headers.get('Upgrade');
        if (!upgradeHeader || upgradeHeader.toLowerCase() !== 'websocket') {
            return new Response('Expected WebSocket upgrade', { status: 426 });
        }

        const [client, server] = Object.values(new WebSocketPair());
        this.state.acceptWebSocket(server);

        const connId = crypto.randomUUID();
        this.sessions.set(connId, { ws: server, presence: null });
        server._connId = connId;

        return new Response(null, {
            status: 101,
            webSocket: client,
            headers: { 'Access-Control-Allow-Origin': '*' },
        });
    }

    async webSocketMessage(ws, rawMsg) {
        const connId = ws._connId;
        if (!connId || !this.sessions.has(connId)) return;

        let msg;
        try {
            msg = JSON.parse(rawMsg);
        } catch {
            return;
        }

        if (!msg.type) return;

        if (msg.type === 'presence') {
            // Update stored presence for this connection
            this.sessions.get(connId).presence = {
                id: connId,
                x: msg.x,
                y: msg.y,
                z: msg.z,
                yaw: msg.yaw,
                nickname: msg.nickname || 'anon',
                color: msg.color || '#00ff88',
                nodeId: msg.nodeId || null,
            };

            // Broadcast full presence snapshot to everyone
            this._broadcastPresenceSnapshot(connId);
        } else if (msg.type === 'chat') {
            if (!msg.text || typeof msg.text !== 'string') return;
            const chatMsg = JSON.stringify({
                type: 'chat',
                id: connId,
                nickname: msg.nickname || 'anon',
                color: msg.color || '#00ff88',
                text: msg.text.slice(0, 300),
                ts: Date.now(),
            });
            this._broadcast(chatMsg, null);
        }
    }

    async webSocketClose(ws) {
        const connId = ws._connId;
        if (!connId) return;
        this.sessions.delete(connId);
        this._broadcastPresenceSnapshot(null);
        this._broadcast(JSON.stringify({ type: 'leave', id: connId }), null);
    }

    async webSocketError(ws) {
        const connId = ws._connId;
        if (connId) this.sessions.delete(connId);
    }

    _broadcastPresenceSnapshot(excludeId) {
        const all = [];
        for (const [id, session] of this.sessions) {
            if (session.presence) all.push(session.presence);
        }
        const msg = JSON.stringify({ type: 'presence_snapshot', users: all });
        this._broadcast(msg, excludeId);
    }

    _broadcast(msg, excludeId) {
        for (const [id, session] of this.sessions) {
            if (id === excludeId) continue;
            try {
                session.ws.send(msg);
            } catch {
                this.sessions.delete(id);
            }
        }
    }
}

function jsonResponse(body, status, corsHeaders) {
    return new Response(JSON.stringify(body), {
        status,
        headers: {
            'Content-Type': 'application/json',
            ...corsHeaders,
        },
    });
}

function corsHeaders() {
    return {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    };
}

async function readJsonResponse(response) {
    const text = await response.text();
    try {
        return JSON.parse(text);
    } catch {
        throw new Error(`OAuth upstream returned non-JSON: ${text}`);
    }
}

async function exchangeGitHubToken(request, env, headers) {
    const { code, state } = await request.json();
    const tokenBody = new URLSearchParams();
    tokenBody.set('client_id', env.CODEFLY_GITHUB_APP_CLIENT_ID);
    tokenBody.set('client_secret', env.CODEFLY_GITHUB_APP_CLIENT_SECRET);
    tokenBody.set('code', code);
    tokenBody.set('state', state);
    const response = await fetchGitHubToken(tokenBody);
    const data = await readJsonResponse(response);
    return jsonResponse(data, response.status, headers);
}

function fetchGitHubToken(tokenBody) {
    return fetch('https://github.com/login/oauth/access_token', {
        method: 'POST',
        headers: githubTokenHeaders(),
        body: tokenBody.toString(),
    });
}

function githubTokenHeaders() {
    return {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Accept': 'application/json',
        'User-Agent': 'CodeFly',
    };
}

async function fetchGitHubUser(request, headers) {
    const { access_token } = await request.json();
    const response = await fetch('https://api.github.com/user', {
        headers: {
            'Authorization': `Bearer ${access_token}`,
            'User-Agent': 'CodeFly',
        },
    });
    const data = await readJsonResponse(response);
    return jsonResponse(data, response.status, headers);
}

async function exchangeGitLabToken(request, env, headers) {
    const { code } = await request.json();
    const tokenBody = new URLSearchParams();
    tokenBody.set('client_id', env.CODEFLY_GITLAB_APP_APPLICATION_ID);
    tokenBody.set('client_secret', env.CODEFLY_GITLAB_APP_APPLICATION_SECRET);
    tokenBody.set('code', code);
    tokenBody.set('grant_type', 'authorization_code');
    tokenBody.set('redirect_uri', 'https://sugarspacejam.github.io/codefly/');
    const response = await fetchGitLabToken(tokenBody);
    const data = await readJsonResponse(response);
    return jsonResponse(data, response.status, headers);
}

function fetchGitLabToken(tokenBody) {
    return fetch('https://gitlab.com/oauth/token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: tokenBody.toString(),
    });
}

async function fetchGitLabUser(request, headers) {
    const { access_token } = await request.json();
    const response = await fetch('https://gitlab.com/api/v4/user', {
        headers: { 'Authorization': `Bearer ${access_token}` },
    });
    const data = await readJsonResponse(response);
    return jsonResponse(data, response.status, headers);
}

export default {
    async fetch(request, env) {
        const url = new URL(request.url);
        const headers = corsHeaders();
        if (request.method === 'OPTIONS') {
            return new Response(null, { headers });
        }

        try {
            if (url.pathname === '/github/oauth/authorize' && request.method === 'POST') {
                return exchangeGitHubToken(request, env, headers);
            }

            if (url.pathname === '/github/oauth/user' && request.method === 'POST') {
                return fetchGitHubUser(request, headers);
            }

            if (url.pathname === '/gitlab/oauth/authorize' && request.method === 'POST') {
                return exchangeGitLabToken(request, env, headers);
            }

            if (url.pathname === '/gitlab/oauth/user' && request.method === 'POST') {
                return fetchGitLabUser(request, headers);
            }
        } catch (error) {
            return jsonResponse({ error: error.message }, 500, headers);
        }

        return jsonResponse({ error: 'OAuth proxy route not found' }, 404, headers);
    },
};

