            remoteUrl = `https://github.com/${repoMeta.repo}/blob/${repoMeta.branch}/${node.fullPath}#L${lineNumber}`;
        } else if (repoMeta.provider === 'gitlab' && repoMeta.repo && repoMeta.branch) {
