    highlightExecutionSymbolLane(symbolEdge);
    updateExecutionPathPanel(selectedNodeId);
    const destination = focusNodeId || symbolEdge.toFile;
    if (destination && nodeMeshes.has(destination)) {
        flyToNode(destination);
