    localStorage.removeItem(RECENT_REPOS_STORAGE_KEY);
    const container = document.getElementById('recentRepos');
    if (!container) {
        throw new Error('Recent repos container missing from DOM');
    }
    container.innerHTML = '';
}


function showLoadError(msg) {
    const el = document.getElementById('loadError');
    el.textContent = msg;
    el.style.display = 'block';
}


function hideLoadError() {
    document.getElementById('loadError').style.display = 'none';
}


function updateAuthUi() {
    const status = document.getElementById('authStatus');
    const logoutBtn = document.getElementById('logoutBtn');
    if (authState.provider) {
        if (status) status.textContent = `Logged in as ${authState.userLabel}`;
        if (logoutBtn) logoutBtn.style.display = 'inline-block';
    } else {
        if (status) status.textContent = 'Not connected';
        if (logoutBtn) logoutBtn.style.display = 'none';
    }
}

// @ts-check

/** @typedef {import('./types/graph-contract').GraphData} GraphData */

/**
 * @param {GraphData} graph
 */
function assertGraphContract(graph) {
  graph.nodes.forEach((node) => {
    node.id;
    node.fullPath;
    node.definitions.forEach((definition) => {
      definition.name;
      definition.line;
      definition.kind;
    });
  });

  graph.edges.forEach((edge) => {
    edge.from;
    edge.to;
  });

  graph.symbolEdges.forEach((edge) => {
    edge.fromFile;
    edge.toFile;
    edge.fromSymbol;
    edge.toSymbol;
    edge.callLine;
    edge.type;
  });

  graph.meta.parseSummary.full;
  graph.meta.parseSummary.partial;
  graph.meta.parseSummary.unsupported;
}

module.exports = { assertGraphContract };

export type ParseStatus = 'full' | 'partial' | 'unsupported';

export interface GraphDefinition {
  name: string;
  line: number;
  kind: string;
}

export interface GraphNode {
  id: string;
  label: string;
  folder: string;
  lines: number;
  fullPath: string;
  definitions: GraphDefinition[];
  lang: string;
  preview: string[];
  rawPreview: string[];
  parseStatus: string;
  parseReason: string;
  size: number;
}

export interface GraphEdge {
  from: string;
  to: string;
}

export interface SymbolEdge {
  fromFile: string;
  toFile: string;
  fromSymbol: string;
  toSymbol: string;
  fromKind: string;
  toKind: string;
  fromLine: number;
  toLine: number;
  callLine: number;
  type: 'static-call';
}

export interface GraphMeta {
  languages: Record<string, number>;
  parseSummary: Record<string, number>;
  unsupportedExtensions: string[];
  totalFiles: number;
  generatedAt: string;
  repo?: string;
  branch?: string;
  provider?: string;
}

export interface GraphData {
  nodes: GraphNode[];
  edges: GraphEdge[];
  symbolEdges: SymbolEdge[];
  meta: GraphMeta;
}
